<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Inventario | Deportes Total</title>
<style>*{box-sizing:border-box;font-family:Arial,Helvetica,sans-serif}body{margin:0;background:#eef1f3;color:#263238}.topbar{background:#263f59;color:#fff;padding:15px 25px;border-bottom:4px solid #1b3045;display:flex;justify-content:space-between}.topbar a{color:#fff;text-decoration:none}.container{max-width:1150px;margin:28px auto;padding:0 18px}.grid{display:grid;grid-template-columns:340px 1fr;gap:18px}.card{background:#fff;border:1px solid #cbd3da;padding:20px;margin-bottom:18px}h2,h3{color:#263f59;margin-top:0}.field{margin-bottom:13px}.field label{display:block;font-weight:bold;margin-bottom:6px}.field select,.field input{width:100%;padding:10px;border:1px solid #bdc8d1}.btn{display:inline-block;padding:10px 14px;background:#315f85;color:#fff;border:0;border-radius:3px;cursor:pointer;text-decoration:none}.msg{padding:12px;margin:12px 0;background:#e8f2e8;border-left:4px solid #4b8a4b}.msg.error{background:#ffeded;border-color:#b33}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;min-width:610px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e3e7ea}th{background:#e9eef2;font-size:12px;text-transform:uppercase}.muted{color:#6c7a86;font-size:13px}@media(max-width:850px){.grid{grid-template-columns:1fr}.topbar{gap:10px;flex-direction:column}}</style><link rel="stylesheet" href="<?= base_url('assets/css/app-sidebar.css') ?>">
</head><body class="app-layout">
<?php $this->load->view('partials/sidebar'); ?><header class="topbar"><strong>DEPORTES TOTAL | Inventario</strong><a href="<?= site_url('inicio') ?>">Volver al panel</a></header><main class="container"><h2>Control de inventario</h2><p class="muted">Registra entradas y salidas manuales. Las ventas descuentan unidades automáticamente.</p><div class="grid"><section class="card"><h3>Registrar movimiento</h3><form method="post" action="<?= site_url('inventario/ajustar') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><div class="field"><label>Producto</label><select name="producto_id" required><option value="">Selecciona</option><?php foreach($productos as $p): ?><option value="<?= (int)$p->id ?>"><?= html_escape($p->nombre) ?> | <?= html_escape($p->referencia) ?> | Talla <?= html_escape($p->talla) ?> (<?= (int)$p->stock ?> disp.)</option><?php endforeach; ?></select></div><div class="field"><label>Tipo de movimiento</label><select name="tipo" required><option value="entrada">Entrada</option><option value="salida">Salida</option></select></div><div class="field"><label>Cantidad</label><input type="number" name="cantidad" min="1" step="1" required></div><div class="field"><label>Motivo</label><input name="motivo" maxlength="180" required placeholder="Ej. Compra a proveedor"></div><button class="btn" type="submit">Guardar movimiento</button></form></section><section class="card"><h3>Existencias actuales</h3><div class="scroll"><table><thead><tr><th>Producto</th><th>Referencia</th><th>Talla</th><th>Stock</th></tr></thead><tbody><?php foreach($productos as $p): ?><tr><td><?= html_escape($p->nombre) ?></td><td><?= html_escape($p->referencia) ?></td><td><?= html_escape($p->talla) ?></td><td><strong><?= (int)$p->stock ?></strong></td></tr><?php endforeach; ?></tbody></table></div></section></div><section class="card"><h3>Últimos movimientos</h3><div class="scroll"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Motivo</th><th>Usuario</th></tr></thead><tbody><?php if(empty($movimientos)): ?><tr><td colspan="6">Todavía no hay movimientos registrados.</td></tr><?php else: foreach($movimientos as $m): ?><tr><td><?= html_escape($m->fecha) ?></td><td><?= html_escape($m->producto) ?> (<?= html_escape($m->talla) ?>)</td><td><?= ucfirst(html_escape($m->tipo)) ?></td><td><?= (int)$m->cantidad ?></td><td><?= html_escape($m->motivo) ?></td><td><?= html_escape($m->usuario) ?></td></tr><?php endforeach; endif; ?></tbody></table></div></section></main></body></html>
